import{_ as a,o as t,c as i,ag as n}from"./chunks/framework.HcBc_Mb9.js";const p=JSON.parse('{"title":"What is Generative AI?","description":"","frontmatter":{},"headers":[],"relativePath":"ai-fluency/06-genai.md","filePath":"ai-fluency/06-genai.md"}'),o={name:"ai-fluency/06-genai.md"};function r(s,e,l,c,d,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="what-is-generative-ai" tabindex="-1">What is Generative AI? <a class="header-anchor" href="#what-is-generative-ai" aria-label="Permalink to &quot;What is Generative AI?&quot;">​</a></h1><h2 id="genai-fundamentals" tabindex="-1">GenAI Fundamentals <a class="header-anchor" href="#genai-fundamentals" aria-label="Permalink to &quot;GenAI Fundamentals&quot;">​</a></h2><p>This chapter introduces the concept of generative AI, focusing on its ability to create new content rather than just analyzing what already exists. We walk through how large language models (LLMs) like Claude actually work and the technological journey that made them possible, from algorithmic breakthroughs like the transformer architecture to vast training datasets and powerful computing. We also explain how these systems learn through pre-training and fine-tuning and discuss concepts like context windows and emergent capabilities.</p><h2 id="key-concepts" tabindex="-1">Key concepts <a class="header-anchor" href="#key-concepts" aria-label="Permalink to &quot;Key concepts&quot;">​</a></h2><ul><li><strong>Generative models</strong>: predict the next token to produce new text/code/media.</li><li><strong>Context window</strong>: how much input the model can see at once.</li><li><strong>Sampling controls</strong>: temperature/top_p to balance creativity vs. stability.</li><li><strong>Hallucination</strong>: confident but wrong outputs—always verify.</li><li><strong>Guardrails</strong>: policies, filters, and prompts to keep use safe.</li></ul><h2 id="good-use-cases" tabindex="-1">Good use cases <a class="header-anchor" href="#good-use-cases" aria-label="Permalink to &quot;Good use cases&quot;">​</a></h2><ul><li>Brainstorming, outlining, first drafts</li><li>Summaries and rewrites (with human review)</li><li>Classification, extraction, light data cleanup</li></ul><h2 id="caution-zones" tabindex="-1">Caution zones <a class="header-anchor" href="#caution-zones" aria-label="Permalink to &quot;Caution zones&quot;">​</a></h2><ul><li>Factual/critical content without verification</li><li>Sensitive data, privacy/regulatory constraints</li><li>Long reasoning chains that need reliable intermediate steps</li></ul><h2 id="practice" tabindex="-1">Practice <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;Practice&quot;">​</a></h2><ul><li>Draft a short outline with GenAI; then add a review checklist and fix any gaps.</li></ul><h2 id="downloads" tabindex="-1">Downloads <a class="header-anchor" href="#downloads" aria-label="Permalink to &quot;Downloads&quot;">​</a></h2><div style="border-radius:18px;background:#d2cfe3;padding:28px;display:flex;gap:24px;align-items:center;"><div style="flex:0 0 140px;text-align:center;"><div style="width:120px;height:120px;margin:0 auto;border-radius:18px;background:#f5f3f7;display:flex;align-items:center;justify-content:center;"><span style="font-size:64px;line-height:1;color:#2d2a32;">✍️</span></div></div><div style="flex:1;"><h3 style="margin:0 0 10px 0;font-size:28px;color:#2d2a32;">Overview of Generative AI</h3><p style="margin:0 0 18px 0;font-size:18px;color:#2d2a32;line-height:1.6;"> Quick reference guide for understanding generative AI. </p><a href="/anthropic-notes/ai-fluency/DD1_Handout__Overview_of_Generative_AI.pdf" style="display:inline-block;padding:12px 22px;border-radius:12px;background:#6f6a80;color:#ffffff;text-decoration:none;font-weight:600;">Download</a></div></div>',13)])])}const g=a(o,[["render",r]]);export{p as __pageData,g as default};
